// footerFrameConsumers lists every package under internal/ui whose Update takes
// a jobs.FrameMsg, and what it does with it for the footer: the view whose seed
// in footerActivitySeeds proves the dot, or the reason the package is exempt.
// A package that starts handling jobs.FrameMsg fails the test below until it is
// written down here (DEVDESK-341, plan section 3).
var footerFrameConsumers = map[string]struct {
	View   command.ViewType // set: the footer shows the dot, seeded in footerActivitySeeds
	Exempt string           // set: why the footer keeps its own spinner or has none
}{
	"ui/dashboard":      {View: command.ViewDashboard},
	"ui/jobsview":       {View: command.ViewJobs},
	"ui/workspaces":     {View: command.ViewWorkspaces},
	"ui/templates":      {View: command.ViewTemplates},
	"ui/security":       {View: command.ViewSecurity},
	"ui/oci_resources":  {View: command.ViewOCIResources},
	"ui/forge/explorer": {View: command.ViewGitExplorer},
	"ui/status":         {View: command.ViewStatus},
	"ui/viewer":         {View: command.ViewViewer},
	"ui/containers":     {View: command.ViewContainers},
	"ui/agentusageview": {View: command.ViewAgentUsage},
	"ui/netdiag":        {View: command.ViewNetdiag},
	"ui/forge/auth":     {View: command.ViewGitAuth},
}

// footerFrameConsumerProblems compares the packages found handling a
// jobs.FrameMsg with the classification table.
func footerFrameConsumerProblems(found map[string]bool, table map[string]struct {
	View   command.ViewType
	Exempt string
}, seeds map[command.ViewType]footerSeed) []string {
	var out []string
	for dir := range found {
		c, ok := table[dir]
		switch {
		case !ok:
			out = append(out, fmt.Sprintf("%s handles jobs.FrameMsg but is in neither footerActivitySeeds nor an exemption (footerFrameConsumers)", dir))
		case c.View != "" && c.Exempt != "":
			out = append(out, fmt.Sprintf("%s is both seeded and exempt", dir))
		case c.View == "" && c.Exempt == "":
			out = append(out, fmt.Sprintf("%s is classified without a view or a reason", dir))
		case c.View != "" && seeds[c.View] == nil:
			out = append(out, fmt.Sprintf("%s names view %q, which has no footer seed", dir, c.View))
		}
	}
	for dir := range table {
		if !found[dir] {
			out = append(out, fmt.Sprintf("footerFrameConsumers lists %s, which no longer handles jobs.FrameMsg: drop the entry", dir))
		}
	}
	for vt := range seeds {
		listed := false
		for _, c := range table {
			listed = listed || c.View == vt
		}
		if !listed {
			out = append(out, fmt.Sprintf("footerActivitySeeds has view %q, which footerFrameConsumers does not map to a consumer", vt))
		}
	}
	sort.Strings(out)
	return out
}

// frameConsumerSeeds is every view with a footer-dot seed: the jobs-driven ones
// and the ones that load on their own (footerLoadingSeeds, DEVDESK-369).
func frameConsumerSeeds() map[command.ViewType]footerSeed {
	out := map[command.ViewType]footerSeed{}
	for vt, seed := range footerActivitySeeds {
		out[vt] = seed
	}
	for vt, seeds := range footerLoadingSeeds {
		if len(seeds) > 0 {
			out[vt] = seeds[0].seed
		}
	}
	return out
}

func TestActivityGuardFrameConsumersAreClassifiedLogic(t *testing.T) {
	type entry = struct {
		View   command.ViewType
		Exempt string
	}
	seeds := map[command.ViewType]footerSeed{command.ViewDashboard: seedDashboardActivity}
	good := map[string]entry{"ui/dashboard": {View: command.ViewDashboard}, "ui/x": {Exempt: "own spinner"}}
	if p := footerFrameConsumerProblems(map[string]bool{"ui/dashboard": true, "ui/x": true}, good, seeds); len(p) != 0 {
		t.Errorf("a classified set reported %v", p)
	}
func seedAgentUsageFooter(t *testing.T, a *App) indicator.State {
	t.Helper()
	live, _ := openLiveAgentSession(t)
	a.views[command.ViewAgentUsage] = live.views[command.ViewAgentUsage]
	return indicator.Running
}

// DEVDESK-371..376: no view owns a braille spinner any more. Every loading state
// is the shared activity dot, driven by the router frame. A package under
// internal/ui that still imports bubbles/v2/spinner is listed here with the story
// that removes it; each step drops its line, and the map ends empty and stays
// empty as the final guard.
const bubblesSpinnerPath = "charm.land/bubbles/v2/spinner"

var pendingSpinnerImports = map[string]string{}

// importsBubblesSpinner reports whether file imports bubbles/v2/spinner, under
// any alias (a blank or dot import counts too).
func importsBubblesSpinner(file *ast.File) bool {
	for _, imp := range file.Imports {
		if path, err := strconv.Unquote(imp.Path.Value); err == nil && path == bubblesSpinnerPath {
			return true
		}
	}
	return false
}

// spinnerImportProblems compares the packages found importing the spinner with
// the pending list.
func spinnerImportProblems(found map[string]bool, pending map[string]string) []string {
	var out []string
	for dir := range found {
		if _, ok := pending[dir]; !ok {
			out = append(out, fmt.Sprintf("%s imports %s: use the shared activity dot (Status.Activity, WantsBlink, jobs.FrameMsg), or list it in pendingSpinnerImports with its story", dir, bubblesSpinnerPath))
		}
	}
	for dir, story := range pending {
		if !found[dir] {
			out = append(out, fmt.Sprintf("pendingSpinnerImports lists %s (%s), which no longer imports the spinner: drop the entry", dir, story))
		}
	}
	sort.Strings(out)
	return out
}

func TestNoViewImportsTheBubblesSpinnerLogic(t *testing.T) {
	parse := func(src string) *ast.File {
		f, err := parser.ParseFile(token.NewFileSet(), "v.go", src, parser.ImportsOnly)
		if err != nil {
			t.Fatal(err)
		}
		return f
	}
	if importsBubblesSpinner(parse("package v\nimport \"fmt\"\n")) {
		t.Error("a file with no spinner import was flagged")
	}
	for name, src := range map[string]string{
		"plain":   "package v\nimport \"" + bubblesSpinnerPath + "\"\n",
		"aliased": "package v\nimport sp \"" + bubblesSpinnerPath + "\"\n",
		"blank":   "package v\nimport _ \"" + bubblesSpinnerPath + "\"\n",
	} {
		if !importsBubblesSpinner(parse(src)) {
			t.Errorf("%s spinner import not detected", name)
		}
	}
	if p := spinnerImportProblems(map[string]bool{"ui/a": true}, map[string]string{}); len(p) != 1 {
		t.Errorf("an unlisted importer: %v", p)
	}
	if p := spinnerImportProblems(map[string]bool{}, map[string]string{"ui/a": "DEVDESK-1"}); len(p) != 1 {
		t.Errorf("a stale entry: %v", p)
	}
	if p := spinnerImportProblems(map[string]bool{"ui/a": true}, map[string]string{"ui/a": "DEVDESK-1"}); len(p) != 0 {
		t.Errorf("a listed importer reported %v", p)
	}
}

func TestNoViewImportsTheBubblesSpinner(t *testing.T) {
	found := map[string]bool{}
	sourceFiles(t, func(rel string, _ *token.FileSet, file *ast.File) {
		if strings.HasPrefix(rel, "ui/") && importsBubblesSpinner(file) {
			found[filepath.ToSlash(filepath.Dir(rel))] = true
		}
	})
	for _, p := range spinnerImportProblems(found, pendingSpinnerImports) {
		t.Error(p)
	}
}

